from pybricks.hubs import PrimeHub
from pybricks.tools import wait

from MBC_laser8_Lib import laser_ch, laser_distances, laser_init_port_multitask, laser_init_status, laser_is_ok, laser_min_direction, laser_min_distance, laser_read_all

# Set up all devices.
prime_hub = PrimeHub()


# The main program starts here.
laser_init_port_multitask(3, False)
while True:
    print(laser_ch(1), laser_ch(2), laser_ch(3), laser_ch(4), laser_ch(5), laser_ch(6), laser_ch(7), laser_ch(8))
    wait(10)
# # ════════════════════════════════════════════════════════════════
# #  【函式說明庫】 (務必確認MBC_laser8_Lib.py位於在左側列表中)
# #
# #  1. 初始化：
# #     laser_init_port_multitask(port, multitask)
# #       - 說明：初始化感測器並指定連接埠。
# #       - 參數：port 填寫 1~6，分別對應 SPIKE 主機的 A~F 埠。
# #       - 參數：multitask 填寫 true/false，分別對應 多工任務與非多工任務。
# #
# #  2. 獨立通道讀取：
# #     laser_ch(ch)
# #       - 說明：讀取指定單一通道的距離數值。
# #       - 參數：ch 填寫 1~8，代表第 1~8 號感測器。
# #       - 回傳：整數 0~120（公分，數值越小代表越近，120 代表無目標或超過 120cm）。
# #
# #     laser_is_ok(ch)
# #       - 說明：檢查指定通道的感測器硬體是否正常連線與初始化。
# #       - 回傳：True (正常) / False (異常、損壞或排線鬆脫)。
# #
# #  3. 整體狀態分析：
# #     laser_min_direction()
# #       - 說明：回傳當前距離「最近」的目標落在哪個感測器方向。
# #       - 回傳：整數 0~16（方位，8 = 正前方，越小越偏左、越大越偏右）。
# #
# #     laser_min_distance()
# #       - 說明：回傳當前「最近目標」的距離數值。
# #       - 回傳：整數 0~120（公分）。
# #
# #     laser_distances()
# #       - 說明：一次取得所有 8 顆感測器的距離陣列。
# #       - 回傳：長度為 8 的整數陣列 (list)，例如 [120, 50, 120, ...]。
# #
# #     laser_init_status()
# #       - 說明：一次取得所有 8 顆感測器的連線狀態陣列。
# #       - 回傳：長度為 8 的布林值陣列 (list)，例如 [True, True, False, ...]。
# #
# #     laser_read_all()
# #       - 說明：一次取得所有解析完畢的綜合狀態字典 (Dictionary)。
# # ════════════════════════════════════════════════════════════════
